<script setup lang="ts">import { onMounted } from 'vue'; import AppLayout from '../components/layout/AppLayout.vue'; import BaseCard from '../components/ui/BaseCard.vue'; import { useUserStore } from '../stores/user/store'; const store = useUserStore(); onMounted(() => store.fetchAll())</script>
